def move_recovery_codes(apps, schema_editor):
    """Recovery codes now belong to the account (any second factor), not to the authenticator app."""
    import base64
    import secrets

    TwoFactorDevice = apps.get_model('console', 'TwoFactorDevice')
    SignInSecurity = apps.get_model('console', 'SignInSecurity')
    for device in TwoFactorDevice.objects.exclude(recovery_codes=[]):
        handle = base64.urlsafe_b64encode(secrets.token_bytes(32)).rstrip(b'=').decode()
        SignInSecurity.objects.update_or_create(
            user_id=device.user_id, defaults={'recovery_codes': device.recovery_codes},
            create_defaults={'user_handle': handle, 'recovery_codes': device.recovery_codes})


